buy_code:
# ================================
#  오전 모멘텀 (min 풀세션) — 시간 확대 축: entry_end
# ================================
매수 = True

if not (관심종목 == 1):
    매수 = False
elif not (90100 <= 시분초 < {entry_end}):
    매수 = False
elif not (데이터길이 > 30):
    매수 = False
elif not (1000 < 현재가 <= {price_max}):
    매수 = False
elif not ({rate_min} < 등락율 <= {rate_max}):
    매수 = False
elif not (시가총액 < {cap_max}):
    매수 = False
elif not (고저평균대비등락율 > 0):
    매수 = False
elif 라운드피겨위5호가이내:
    매수 = False
elif not (전일동시간비 > {prev_ratio_min}):
    매수 = False
elif not (당일거래대금 > 50 * 100):
    매수 = False
elif not (분당거래대금 > 분당거래대금평균(30) * {burst_min}):
    매수 = False
elif not (현재가 > 최고현재가({breakout_lookback}, 1)):
    매수 = False
elif not (체결강도 >= {strength_min}):
    매수 = False
elif not (분당매수수량 > 분당매도수량):
    매수 = False

if 매수:
    self.Buy()

sell_code:
# ================================
#  오전 모멘텀 매도 (min) — 보유시간 단위: 분
# ================================
매도 = False

if 등락율 > 29.5:
    매도 = True
elif 수익률 >= {take_hard}:
    매도 = True
elif 수익률 <= {stop_hard}:
    매도 = True
elif 최고수익률 > {trail_start} and 최고수익률 * {trail_keep} >= 수익률:
    매도 = True
elif 보유시간 > {max_hold_min}:
    매도 = True
elif 시분초 >= 151500:
    매도 = True

if 매도:
    self.Sell()
